CREATE TABLE mytable(
   Account_ID      NUMERIC(7,1) NOT NULL PRIMARY KEY 
  ,Username        VARCHAR(19)
  ,Platform        VARCHAR(9)
  ,Follower_Count  NUMERIC(8,1)
  ,Posts_Per_Week  NUMERIC(3,1)
  ,Engagement_Rate NUMERIC(6,4)
  ,Ad_Spend_USD    NUMERIC(6,2)
  ,Conversion_Rate NUMERIC(6,4)
  ,Campaign_Reach  NUMERIC(7,1)
);
